    squigboss:{profile:[["Squigboss",4,3,3,4,4,2,3,2,6],["Gnasha-Squig","*",4,0,4,"–","–",3,2,3]],eq:"Great weapon, light armour",rules:"Fear Elves, Hatred (Dwarfs), Loner; Mycophile's Pouch; Squigboss (may join Squig Herds)."},
