    boarboyz:{profile:[["Orc",4,3,3,4,4,1,2,1,7],["War Boar",7,3,0,3,4,1,3,1,3]],eq:"Hand weapon",rules:"Animosity, Natural Armour (6+), Size Matters, Tusker Charge (War Boar)."},
    arrerboyz:{profile:[["Orc",4,3,3,4,4,1,2,1,7]],eq:"Hand weapon, longbow",rules:"Animosity, Size Matters. May upgrade to Savage Orcs."},
