    fanatics:{profile:[["Fanatic","*","–","–",5,3,1,3,"*",10]],eq:"Giant ball and chain",rules:"Immunity (Psychology), Random Movement (2D6); Fanatic; Splat!."},
    wolfriders:{profile:[["Goblin",4,2,3,3,3,1,2,1,6],["Giant Wolf",9,3,0,3,3,1,3,1,3]],eq:"Hand weapon",rules:"Animosity, Fast Cavalry, Fear Elves."},
    spiderriders:{profile:[["Goblin",4,2,3,3,3,1,2,1,6],["Giant Spider",7,3,0,3,3,1,3,1,2]],eq:"Hand weapon",rules:"Animosity, Fast Cavalry, Fear Elves, Natural Armour (6+), Poisoned Attacks (Giant Spiders), Wall-crawler."},
