    boarchariot:{profile:[["Boar Chariot",6,"–","–",5,5,4,"–","–","–"],["Orc","–",3,3,3,"–","–",2,1,7],["War Boar","–",3,0,3,"–","–",3,1,"–"]],eq:"Hand weapon, light armour",rules:"Mighty Blow (1) (Orc), Natural Armour (6+), Size Matters, Tusker Charge (War Boar). Chariot (Armour Save 6+), 2 crew, 2 War Boars."},
    blackorcs:{profile:[["Black Orc",4,4,3,4,4,1,2,1,8]],eq:"Hand weapon, medium armour",rules:"Armed to da Teef, Immunity (Psychology), Mighty Blow (1)."},
