    azhag:{profile:[["Azhag the Slaughterer",4,7,3,5,5,3,5,4,9],["Skullmuncha (Wyvern)",4,5,0,6,5,5,3,3,6]],eq:"Slagga's Slashas, Azhag's 'Ard Armour, Daemon Staff, Crown of Sorcery",rules:"Fly (8), Mighty Blow (1), Natural Armour (4+), Poisoned Attacks (Skullmuncha), Size Matters, Waaagh!; Get on Wiv it!. Wizard L2 — Death. Must be Army General."},
